#include "PluginEditor.h"
void VST3VocalChainDiagEditor::paint(juce::Graphics& g){ g.fillAll(juce::Colour(0xff0b0d18)); g.setColour(juce::Colour(0xff9b5cff)); g.drawRoundedRectangle(getLocalBounds().toFloat().reduced(12),12.0f,2.0f); g.setColour(juce::Colours::white); g.setFont(30.0f); g.drawText("VST3VocalChain+",30,45,getWidth()-60,45,juce::Justification::centred); g.setFont(16.0f); g.drawText("FL Studio diagnostic build - audio pass-through",30,105,getWidth()-60,30,juce::Justification::centred); g.drawText("Vendor: 29YURO | VST3 Effect | 64-bit",30,145,getWidth()-60,30,juce::Justification::centred); }
